641	16	\N	1	1	availability_report_records	\N	payment.availability_report_records	qweb	payment/views/payment_form_templates.xml	primary	{"en_US": "<t t-name=\\"payment.availability_report_records\\">\\n        <!-- Parameters description:\\n            - records: The records to list in the availability report, as a dict with the structure\\n                       {record: {'available': bool, 'reason': str, supported_providers: list}}.\\n        -->\\n        <ul class=\\"list-group\\">\\n            <t t-foreach=\\"records\\" t-as=\\"r\\">\\n                <t t-set=\\"available\\" t-value=\\"records[r]['available']\\"/>\\n                <li class=\\"list-group-item ps-0\\">\\n                    <div class=\\"d-flex gap-2\\">\\n                        <div class=\\"ms-2\\">\\n                            <i t-attf-class=\\"fa fa-fw fa-{{'check-circle' if available else 'times-circle'}}\\" t-attf-style=\\"color: {{'green' if available else 'red'}};\\"/>\\n                        </div>\\n                        <div>\\n                            <p class=\\"lead mb-0\\">\\n                                <span class=\\"fw-normal\\"><t t-out=\\"r.name\\"/></span>\\n                                <span class=\\"text-muted\\">(ID: <t t-out=\\"r.id\\"/>)</span>\\n                            </p>\\n                            <t t-if=\\"not available\\">\\n                                <p class=\\"mb-0 fw-light\\">\\n                                    Reason: <t t-out=\\"records[r]['reason']\\"/>\\n                                </p>\\n                            </t>\\n                            <t t-if=\\"r._name == 'payment.method' and 'supported_providers' in records[r]\\">\\n                                <p class=\\"mb-0 fw-light\\">\\n                                    Supported providers:\\n                                     <t t-foreach=\\"records[r]['supported_providers']\\" t-as=\\"p\\">\\n                                        <span t-attf-class=\\"text-{{'success' if p[1] else 'danger'}}\\">\\n                                            <t t-out=\\"p[0].name\\"/>\\n                                        </span>\\n                                        <t t-if=\\"records[r]['supported_providers'][-1] != p\\">,</t>\\n                                    </t>\\n                                </p>\\n                            </t>\\n                        </div>\\n                    </div>\\n                </li>\\n            </t>\\n        </ul>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="payment.availability_report_records">\n        <!-- Parameters description:\n            - records: The records to list in the availability report, as a dict with the structure\n                       {record: {'available': bool, 'reason': str, supported_providers: list}}.\n        -->\n        <ul class="list-group">\n            <t t-foreach="records" t-as="r">\n                <t t-set="available" t-value="records[r]['available']"/>\n                <li class="list-group-item ps-0">\n                    <div class="d-flex gap-2">\n                        <div class="ms-2">\n                            <i t-attf-class="fa fa-fw fa-{{'check-circle' if available else 'times-circle'}}" t-attf-style="color: {{'green' if available else 'red'}};"/>\n                        </div>\n                        <div>\n                            <p class="lead mb-0">\n                                <span class="fw-normal"><t t-out="r.name"/></span>\n                                <span class="text-muted">(ID: <t t-out="r.id"/>)</span>\n                            </p>\n                            <t t-if="not available">\n                                <p class="mb-0 fw-light">\n                                    Reason: <t t-out="records[r]['reason']"/>\n                                </p>\n                            </t>\n                            <t t-if="r._name == 'payment.method' and 'supported_providers' in record