reference" optional="hide" column_invisible="context.get('default_move_type') in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                    <field name="ref" optional="hide"/>\n                    <field name="invoice_user_id" optional="hide" column_invisible="context.get('default_move_type') not in ('out_invoice', 'out_refund', 'out_receipt')" string="Salesperson" widget="many2one_avatar_user"/>\n                    <field name="activity_ids" widget="list_activity" optional="hide"/>\n                    <field name="company_id" groups="base.group_multi_company" options="{'no_create': True}" optional="hide"/>\n                    <field name="company_id" groups="!base.group_multi_company" column_invisible="True"/>\n                    <field name="amount_untaxed_in_currency_signed" string="Tax Excluded" sum="Total" optional="show"/>\n                    <field name="amount_tax_signed" string="Tax" sum="Total" optional="hide"/>\n                    <field name="amount_total_in_currency_signed" string="Total" sum="Total" optional="show" decoration-bf="1" decoration-warning="abnormal_amount_warning" groups="base.group_multi_currency"/>\n                    <field name="amount_total_in_currency_signed" string="Total" sum="Total" optional="hide" decoration-bf="1" decoration-warning="abnormal_amount_warning" groups="!base.group_multi_currency"/>\n                    <field name="amount_residual_signed" string="Amount Due" sum="Amount Due" optional="hide"/>\n                    <field name="currency_id" optional="hide" readonly="state in ['cancel', 'posted']"/>\n                    <field name="company_currency_id" column_invisible="True"/>\n                    <field name="checked" optional="hide" widget="boolean_toggle"/>\n                    <field name="status_in_payment" string="Status" widget="badge" decoration-info="state == 'draft'" decoration-danger="payment_state == 'not_paid' and invoice_date_due &lt; context_today().strftime('%Y-%m-%d')" decoration-warning="payment_state in ('partial', 'in_payment')" decoration-success="payment_state in ('paid', 'reversed')" invisible="payment_state == 'invoicing_legacy' or move_type == 'entry'" optional="show"/>\n                    <field name="move_sent_values" string="Sent" widget="badge" decoration-success="move_sent_values == 'sent'" decoration-danger="move_sent_values == 'not_sent'" column_invisible="context.get('default_move_type') not in ('out_invoice', 'out_refund', 'out_receipt')" optional="hide"/>\n                    <field name="move_type" column_invisible="context.get('default_move_type', True)"/>\n                    <field name="abnormal_amount_warning" column_invisible="1"/>\n                    <field name="abnormal_date_warning" column_invisible="1"/>\n                  </list>\n            	f	t	2026-04-07 03:09:00.605908	2026-04-07 03:09:00.605908	f
702	999	701	1	1	account.duplicated.moves.list.js	account.move	\N	list	account/views/account_move_views.xml	primary	{"en_US": "<data><xpath expr=\\"//list\\" position=\\"attributes\\">\\n                    <attribute name=\\"js_class\\">account_x2many_list</attribute>\\n                    <attribute name=\\"create\\">false</attribute>\\n                </xpath>\\n                <xpath expr=\\"//field[@name='name']\\" position=\\"attributes\\">\\n                    <attribute name=\\"column_invisible\\">True</attribute>\\n                </xpath>\\n                <xpath expr=\\"//field[@name='name']\\" position=\\"after\\">\\n                    <!-- For draft moves, name only displays '/'. Since there may be moves of differenty types,\\n                         it is better to use display_name indicating what move it refers to when in draft-->\\n                    <field name=\\"display_name\\" decoration-bf=\\"1\\" string=\\"Number\\" context=\\"{'name_with_move_type': True}\\" widget=\\"char_with_placeholder_field\\" placeholder=\\"/\\"/>\\n                </xpath>\\n            </data>"}	<?xml version="1.0"?>\n<data><xpath expr="//list" position="attributes">\n                    <attribute name="js_class">account_x2many_list</attribute>\n                    <attribute name="create">false</attribute>\n                </xpath>\n                <xpath expr="//field[@name='name']" position="attributes">\n                    <attribute name="column_invisible">True</attribute>\n                </xpath>\n                <xpath expr="//field[@name='name']" position="after">\n                    <!-- For draft moves, name only displays '/'. Since there may be moves of differenty types,\n                         it is better to use display_name indicating what move it refers to when in draft-->\n                    <field name="display_name" decoration-bf="1" string="Number" context="{'name_with_move_type': True}" widget="char_with_placeholder_field" placeholder="/"/