709	16	\N	1	1	account.move.kanban	account.move	\N	kanban	account/views/account_move_views.xml	primary	{"en_US": "<kanban class=\\"o_kanban_mobile\\" sample=\\"1\\" js_class=\\"account_documents_kanban\\">\\n                    <field name=\\"currency_id\\"/>\\n                    <templates>\\n                        <t t-name=\\"card\\">\\n                            <div class=\\"row mb4\\">\\n                                <div class=\\"col-6\\">\\n                                    <field class=\\"fw-bold\\" name=\\"partner_id\\" invisible=\\"not partner_id\\" readonly=\\"state != 'draft'\\"/>\\n                                    <field class=\\"fw-bold\\" name=\\"journal_id\\" invisible=\\"partner_id\\"/>\\n                                </div>\\n                                <div class=\\"col-6 text-end\\">\\n                                    <i class=\\"fa fa-clock-o fw-bold\\" aria-label=\\"Date\\" role=\\"img\\" title=\\"Date\\"/> <field class=\\"fw-bold\\" name=\\"date\\"/>\\n                                </div>\\n                            </div>\\n                            <field name=\\"ref\\"/>\\n                            <div class=\\"row\\">\\n                                <div class=\\"col-6\\">\\n                                    <field name=\\"amount_total_in_currency_signed\\" widget=\\"monetary\\"/>\\n                                </div>\\n                                <div class=\\"col-6\\">\\n                                    <field class=\\"float-end\\" name=\\"state\\" widget=\\"label_selection\\" options=\\"{'classes': {'draft': 'default', 'posted': 'success'}}\\"/>\\n                                </div>\\n                            </div>\\n                        </t>\\n                    </templates>\\n                </kanban>"}	<?xml version="1.0"?>\n<kanban class="o_kanban_mobile" sample="1" js_class="account_documents_kanban">\n                    <field name="currency_id"/>\n                    <template