er">\n                            <block title="Fiscal Periods" id="accounting_reports">\n                                <setting id="fiscalyear" invisible="1" groups="account.group_account_user"/>\n                                <setting id="dynamic_report" groups="account.group_account_user" help="Navigate easily through reports and see what is behind the numbers">\n                                    <field name="module_account_reports" widget="upgrade_boolean"/>\n                                </setting>\n                            </block>\n                        </t>\n                        <block title="Analytics" id="analytic" groups="account.group_account_user">\n                            <setting id="track_costs_revenues" title="Allows you to use the analytic accounting." groups="account.group_account_user" help="Track costs &amp; revenues by project, department, etc" documentation="/applications/finance/accounting/others/analytic_accounting.html">\n                                <field name="group_analytic_accounting"/>\n                            </setting>\n                            <setting id="account_budget" title="This allows accountants to manage analytic and crossovered budgets. Once the master budgets and the budgets are defined, the project managers can set the planned amount on each analytic account." groups="account.group_account_user" help="Use budgets to compare actual with expected revenues and costs" documentation="/applications/finance/accounting/others/adviser/budget.html">\n                                <field name="module_account_budget" widget="upgrade_boolean"/>\n                            </setting>\n                            <setting id="monitor_product_margins" string="Margin Analysis" help="Monitor your product margins from invoices" groups="account.group_account_user">\n                                <field name="module_product_margin"/>\n                            </setting>\n                        </block>\